using BenchmarkDotNet.Attributes;
using BenchmarkDotNet.Configs;
using BenchmarkDotNet.Environments;
using BenchmarkDotNet.Jobs;
using BenchmarkDotNet.Running;
using TextAnalysis;

[MemoryDiagnoser]
[SimpleJob(RuntimeMoniker.Net90)]
[SimpleJob(RuntimeMoniker.Net100)]
public class TextAnalyzerBenchmarks
{
    private TextAnalyzer _analyzer = null!;

    [GlobalSetup]
    public void Setup()
    {
        // Generate a realistic paragraph of text
        var words = new[]
        {
            "the", "quick", "brown", "fox", "jumps", "over", "the", "lazy", "dog",
            "and", "the", "cat", "sat", "on", "the", "mat", "while", "birds",
            "sing", "in", "the", "tall", "oak", "tree", "beside", "the", "river",
            "performance", "benchmarking", "is", "essential", "for", "understanding",
            "how", "software", "behaves", "under", "different", "conditions"
        };
        // Repeat to get a reasonable-sized input
        var repeated = Enumerable.Repeat(words, 50).SelectMany(w => w);
        _analyzer = new TextAnalyzer(string.Join(" ", repeated));
    }

    [Benchmark]
    public double AverageWordLength() => _analyzer.AverageWordLength();

    [Benchmark]
    public object WordLengthHistogram() => _analyzer.WordLengthHistogram();

    [Benchmark]
    public int UniqueWordCount() => _analyzer.UniqueWordCount();
}

public class Program
{
    public static void Main(string[] args)
        => BenchmarkSwitcher.FromAssembly(typeof(TextAnalyzerBenchmarks).Assembly).Run(args);
}

