 using BenchmarkDotNet.Attributes;
 using BenchmarkDotNet.Configs;
 using BenchmarkDotNet.Environments;
 using BenchmarkDotNet.Jobs;
 using BenchmarkDotNet.Running;
 using BenchmarkDotNet.Toolchains.CsProj;
 using BenchmarkDotNet.Toolchains.DotNetCli;
 using TextAnalysis;

 public class Net9vs10Config : ManualConfig
 {
     public Net9vs10Config()
     {
         var net9 = Job.Default
             .WithRuntime(CoreRuntime.Core90)
             .WithToolchain(CsProjCoreToolchain.NetCoreApp90)
             .WithId("net9.0");

         var net10 = Job.Default
             .WithRuntime(CoreRuntime.CreateForNewVersion("net10.0", ".NET 10.0"))
             .WithToolchain(CsProjCoreToolchain.From(new NetCoreAppSettings("net10.0", null, ".NET 10.0")))
